figs=[list("ABLUEM"),list("LABEMU"),list("UMABTL"),list("AUMTLB")]
opts={"A":list("BMTLHA"),"B":list("UATMBL"),"C":list("BLUMHA"),"D":list("UBTMAL")}
def trans(a,b):
    return {i:(b.index(x) if x in b else None) for i,x in enumerate(a)}
t1=trans(figs[0],figs[1]); t3=trans(figs[2],figs[3]); assert t1==t3
t2=trans(figs[1],figs[2])
def apply(a,t):
    out=[None]*6
    for i,j in t.items():
        if j is not None: out[j]=a[i]
    return out
pred=apply(figs[3],t2)
new=[i for i,x in enumerate(pred) if x is None]
def fits(o):
    return all(o[i]==pred[i] for i in range(6) if pred[i] is not None) and all(o[i] not in figs[3] for i in new)
res=[k for k,o in opts.items() if fits(o)]
assert res==["C"], res
